use chrono::NaiveDate; use std::collections::BTreeMap;

#[derive(Default)]
struct SalaryHistory { by_start: BTreeMap<NaiveDate, Money> }   // effective date -> amount

impl SalaryHistory {
    fn at(&self, when: NaiveDate) -> Option<&Money> {
        self.by_start.range(..=when).next_back().map(|(_, m)| m)   // latest start <= when
    }
    fn current(&self) -> Option<&Money> { self.at(chrono::Utc::now().date_naive()) }
    fn put(&mut self, from: NaiveDate, amount: Money) { self.by_start.insert(from, amount); }
}
